    const pairLeft = block(-0.8, 0, 1.2, 2), pairRight = block(0.8, 0, 1.2, 2), moving = block(7, 7, 0.9, 0.9);
    const ceiling = S.createNode({ geometry: BL.models.box({ w: 3, h: 0.2, d: 4, color: "#665544" }), position: { x: 0, y: 14.2, z: -0.5 } });
