    const wall = S.createNode({ geometry: BL.models.box({ w: 5, h: 2.5, d: 0.2, color: "#665544" }), visible: false });
    const ceiling = S.createNode({ geometry: BL.models.box({ w: 6, h: 0.2, d: 6, color: "#665544" }), visible: false });
