      step(0.4);
      const drift = Math.hypot(a.root.position.x - stopped.x, a.root.position.z - stopped.z), idleYawChange = Math.abs(a.shoulder.yaw - stopped.yaw);
      crew.steer(0, 1, firstPerson ? 1 : 0, 1, 0); step(1.1); crew.steer(0, 0);
