      hud: { setRosterRow: (name, state, ageText, online = false) => rows.set(name, { state, ageText, online }) }, game: { state: { assignments: {}, inventory: [] } },
      pile: { footprintEdge: 1, pileEdge: () => 1 }, groundAt: () => 0, walkable: () => true,
