      const at = Date.now();
      activityEntry.lastCommitAt = at - 2 * 60000; crew.refreshStates();
      const firstAge = rows.get(worker.traits.name).ageText;
      activityEntry.lastCommitAt = at - 3 * 60000; crew.refreshStates();
