    const impact = world(0, 1.5, 0.5); damage.hit(BL.mirrorDamage.MAX_DAMAGE, impact.x, impact.y, impact.z); update(0, elapsed);
    place(cave); key("w", true); step(90); key("w", false); const closed = along(cave.root.position);
