        game: { state: { assignments: {}, inventory: [] } }, pile: { footprintEdge: 1, pileEdge: () => 1 }, viewYaw: 0,
        buildSpots: [], walkIn: { x: 0, z: 3 }, groundAt: () => 0, walkable: clear, npcWalkable: clear, flyable: clear,
